import { atolls } from "@/lib/data";

/** Stable ASCII URLs without losing accents from the names shown to visitors. */
export function destinationSlug(name: string): string {
  return name.normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

export const atollDestinations = atolls.map((name) => {
  const slug = destinationSlug(name);
  // Preserve URLs previously generated by the atoll directory (notably kaafu-mal-).
  const legacySlug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-");
  return { name, slug, aliases: legacySlug === slug ? [] : [legacySlug] };
});

/** Existing destinations already linked from the homepage; no invented entries. */
export const islandDestinations = [
  { slug: "male", name: "Malé" },
  { slug: "maafushi", name: "Maafushi" },
  { slug: "hulhumale", name: "Hulhumalé" },
  { slug: "dhigurah", name: "Dhigurah" },
];

export function findAtollDestination(slug: string) {
  return atollDestinations.find((destination) => destination.slug === slug || destination.aliases.includes(slug));
}

export function findIslandDestination(slug: string) {
  return islandDestinations.find((destination) => destination.slug === slug);
}
